<script setup lang="ts">
import { computed, shallowRef, useId, watch } from 'vue'
import { ArrowDownToLine, Box, Database, ExternalLink, Focus, GitBranch, Minus, Plus, Workflow } from 'lucide-vue-next'
import type { ArchitectureNode, ProjectInsight } from '@/api/insights'
import type { DecompileSourceFile } from '@/api/types'
import { architectureLayout, roleLabels } from './architectureLayout'

const props = defineProps<{ insight: ProjectInsight; files: readonly DecompileSourceFile[] }>()
const emit = defineEmits<{ openFile: [fileId: string] }>()
const selectedId = shallowRef('')
const zoom = shallowRef(1)
const markerId = useId().replace(/:/g, '')
const graph = computed(() => architectureLayout(props.insight.result.nodes, props.insight.result.edges))
const selected = computed(() => props.insight.result.nodes.find(node => node.id === selectedId.value) ?? props.insight.result.nodes[0])
const icons = { entry: Workflow, core: Box, data: Database, external: ExternalLink }
const nodeFiles = (node: ArchitectureNode) => props.files.filter(file => node.fileIds.includes(file.id))
watch(() => props.insight, () => { selectedId.value = ''; zoom.value = 1 })
</script>

<template>
  <div class="architecture-content">
    <div class="architecture-stats"><span><Box :size="14" /><strong>{{ insight.result.nodes.length }}</strong> 职责模块</span><span><GitBranch :size="14" /><strong>{{ insight.result.edges.length }}</strong> 逻辑关系</span><span><ArrowDownToLine :size="14" /><strong>{{ insight.coverage.sampledFiles }}</strong> 已读文件</span><small>点击模块，查看职责与关联代码</small></div>
    <div class="architecture-layout">
      <section class="diagram" aria-label="宏观代码架构图">
        <div class="diagram-toolbar"><span><i /> 模块关系图</span><div><button aria-label="缩小架构图" :disabled="zoom <= .6" @click="zoom = Math.max(.6, zoom - .1)"><Minus :size="14" /></button><span>{{ Math.round(zoom * 100) }}%</span><button aria-label="放大架构图" :disabled="zoom >= 1.5" @click="zoom = Math.min(1.5, zoom + .1)"><Plus :size="14" /></button><button aria-label="重置架构图缩放" @click="zoom = 1"><Focus :size="14" /></button></div></div>
        <div class="diagram-scroll">
          <div :style="{ width: graph.width * zoom + 'px', height: graph.height * zoom + 'px' }">
            <div class="diagram-board" :style="{ width: graph.width + 'px', height: graph.height + 'px', transform: `scale(${zoom})` }">
              <span v-for="(role, index) in graph.columns" :key="role" class="diagram-column" :style="{ left: 36 + index * ((graph.width - 72) / graph.columns.length) + 'px' }">{{ roleLabels[role] }}</span>
              <svg :viewBox="`0 0 ${graph.width} ${graph.height}`" :width="graph.width" :height="graph.height" aria-hidden="true">
                <defs><marker :id="markerId" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#94a3b8" /></marker></defs>
                <g v-for="(edge, index) in graph.paths" :key="index" :class="{ 'edge-active': selected && (edge.from === selected.id || edge.to === selected.id) }"><path :d="edge.d" fill="none" stroke="#b5c4da" stroke-width="1.6" :marker-end="`url(#${markerId})`" /><rect :x="edge.labelX - 43" :y="edge.labelY - 13" width="86" height="20" rx="5" fill="#f8faff" /><text :x="edge.labelX" :y="edge.labelY" text-anchor="middle" fill="#768399" font-size="10">{{ edge.label.length > 8 ? edge.label.slice(0, 8) + '…' : edge.label }}</text></g>
              </svg>
              <button v-for="node in graph.nodes" :key="node.id" class="module-node" :class="[`module-node--${node.role}`, { 'module-node--selected': selected?.id === node.id }]" :style="{ left: node.x + 'px', top: node.y + 'px' }" :aria-pressed="selected?.id === node.id" @click="selectedId = node.id"><span class="module-icon"><component :is="icons[node.role]" :size="19" /></span><span class="module-text"><strong>{{ node.label }}</strong><small>{{ node.description }}</small></span><span class="module-port module-port--in" /><span class="module-port module-port--out" /></button>
            </div>
          </div>
        </div>
        <p class="diagram-caption">AI 推断 · 连线表示模块间可能的调用或数据流向</p>
      </section>
      <aside v-if="selected" class="module-detail"><span class="detail-eyebrow">MODULE INSIGHT</span><div class="detail-title"><component :is="icons[selected.role]" :size="20" /><h3>{{ selected.label }}</h3></div><span class="detail-role">{{ roleLabels[selected.role] }}</span><p>{{ selected.description }}</p><h4>关联源码 <span>{{ nodeFiles(selected).length }}</span></h4><button v-for="file in nodeFiles(selected)" :key="file.id" class="related-file" :title="file.logicalPath" @click="emit('openFile', file.id)"><Box :size="14" /><span>{{ file.logicalPath }}</span><ExternalLink :size="12" /></button><p v-if="!nodeFiles(selected).length" class="detail-empty">抽象职责模块，暂无具体文件关联。</p></aside>
    </div>
    <div class="architecture-story"><section><span class="detail-eyebrow">ARCHITECTURE OVERVIEW</span><h3>代码如何组合在一起</h3><p>{{ insight.result.summary }}</p></section><section v-if="insight.result.flow.length"><span class="detail-eyebrow">EXECUTION FLOW</span><h3>主要执行脉络</h3><ol><li v-for="(step, index) in insight.result.flow" :key="index"><span>{{ String(index + 1).padStart(2, '0') }}</span><p>{{ step }}</p></li></ol></section></div>
  </div>
</template>

